package com.perkvault.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.TextRecognition;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
public class MainActivity extends Activity {
 LinearLayout root,items; String filter="Active",query=""; ArrayDeque<Uri> scans=new ArrayDeque<>(); int ink=0xff18382b;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(ink);getWindow().setNavigationBarColor(ink);home();Reminder.schedule(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);handle(getIntent());}
 void handle(Intent i){if(i.getBooleanExtra("quick",false))form("");else if(Intent.ACTION_SEND.equals(i.getAction())){Uri u=i.getParcelableExtra(Intent.EXTRA_STREAM);if(u!=null){scans.add(u);nextScan();}else form(i.getStringExtra(Intent.EXTRA_TEXT));}else if(Intent.ACTION_SEND_MULTIPLE.equals(i.getAction())){ArrayList<Uri> a=i.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(a!=null){scans.addAll(a);nextScan();}}}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(ink);t.setPadding(0,dp(7),0,dp(7));return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
 void home(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(24),dp(20),dp(24));root.setBackgroundColor(0xfff5f4ec);scroll.addView(root);setContentView(scroll);root.addView(text("PERKVAULT / PERSONAL REWARDS",12));root.addView(text("Your reward wallet",30));root.addView(button("+ Save voucher",()->form("")));root.addView(button("Scan screenshots",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,12);}));root.addView(button("Floating shortcut settings",()->new AlertDialog.Builder(this).setTitle("Floating shortcut").setMessage("Enable only while collecting rewards. Some payment apps block overlays. Stop before making payments.").setPositiveButton("Enable",(d,w)->{if(!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));else startForegroundService(new Intent(this,Bubble.class));}).setNegativeButton("Stop",(d,w)->stopService(new Intent(this,Bubble.class))).show()));root.addView(text("Quick Settings: add the Save voucher tile from Android's tile editor.",13));EditText search=new EditText(this);search.setHint("Search brand, app or code");root.addView(search);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();render();}public void afterTextChanged(android.text.Editable e){}});Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Active","All","Used","Expired","Gift card","Loyalty"}));root.addView(sp);items=new LinearLayout(this);items.setOrientation(1);root.addView(items);sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){filter=p.getItemAtPosition(n).toString();render();}});render();}
 void render(){if(items==null)return;items.removeAllViews();JSONArray a=Store.read(this);double saved=0;int active=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o.optBoolean("used"))saved+=o.optDouble("saved",0);else if(!Store.expired(o))active++;}items.addView(text(active+" active rewards  •  ₹"+String.format(Locale.US,"%.2f",saved)+" saved",18));for(int i=0;i<a.length();i++){final int index=i;JSONObject o=a.optJSONObject(i);boolean used=o.optBoolean("used"),exp=Store.expired(o);if(filter.equals("Active")&&(used||exp)||filter.equals("Used")&&!used||filter.equals("Expired")&&!exp||filter.equals("Gift card")&&!o.optString("type").equals(filter)||filter.equals("Loyalty")&&!o.optString("type").equals(filter)||!o.toString().toLowerCase().contains(query.toLowerCase()))continue;LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(12),dp(10),dp(12),dp(10));card.setBackgroundColor(Color.WHITE);items.addView(card);card.addView(text(o.optString("brand")+"  /  "+o.optString("source"),20));card.addView(text(o.optString("type")+" • "+(used?"Used":exp?"Expired":"Active")+" • "+o.optString("expiry"),13));card.addView(text(o.optString("details")+"\n"+o.optString("code"),15));card.addView(button("Copy code",()->((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Voucher",o.optString("code")))));card.addView(button(used?"Mark unused":"Mark used / record savings",()->{if(used){try{o.put("used",false);o.put("saved",0);Store.write(this,a);render();}catch(Exception e){}}else{EditText e=new EditText(this);e.setInputType(8194);e.setHint("Actual savings in ₹");new AlertDialog.Builder(this).setTitle("Record savings").setView(e).setPositiveButton("Save",(d,w)->{try{o.put("used",true);o.put("saved",e.getText().length()==0?0:Double.parseDouble(e.getText().toString()));Store.write(this,a);render();}catch(Exception ex){}}).show();}}));card.addView(button("Delete",()->new AlertDialog.Builder(this).setMessage("Delete this reward?").setPositiveButton("Delete",(d,w)->{a.remove(index);Store.write(this,a);render();}).setNegativeButton("Cancel",null).show()));items.addView(text("",5));}}
 void form(String raw){Capture.show(this,raw,()->{render();nextScan();});}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==12&&c==RESULT_OK&&d!=null){if(d.getClipData()!=null)for(int i=0;i<d.getClipData().getItemCount();i++)scans.add(d.getClipData().getItemAt(i).getUri());else if(d.getData()!=null)scans.add(d.getData());nextScan();}}
 void nextScan(){if(scans.isEmpty())return;Uri u=scans.remove();try{var recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);recognizer.process(InputImage.fromFilePath(this,u)).addOnSuccessListener(t->{recognizer.close();form(t.getText());}).addOnFailureListener(e->{recognizer.close();Toast.makeText(this,"Scan failed",0).show();nextScan();});}catch(Exception e){nextScan();}}
}
